import{_ as t,o as a,c as n,ak as o}from"./chunks/framework.B8jO0odJ.js";const h=JSON.parse('{"title":"AI-world visual design handoff","description":"Date: 2026-10-22. Method: built-in image generation (not CLI).\\nStatus: proposed visual concepts, not screenshots, production UI, Unity scenes, or import-ready 3D assets.","frontmatter":{"title":"AI-world visual design handoff","description":"Date: 2026-10-22. Method: built-in image generation (not CLI).\\nStatus: proposed visual concepts, not screenshots, production UI, Unity scenes, or import-ready 3D assets.","source":"docs/media/gdd/gameplay-first/notes/visual-ai-notes.md","category":"Other documents","sourceUpdated":"2026-10-22T22:46:54+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/media/gdd/gameplay-first/notes/visual-ai-notes.md","filePath":"content/docs/media/gdd/gameplay-first/notes/visual-ai-notes.md"}'),s={name:"content/docs/media/gdd/gameplay-first/notes/visual-ai-notes.md"};function i(r,e,l,d,c,p){return a(),n("div",null,[...e[0]||(e[0]=[o(`<div><h1 id="ai-world-visual-design-handoff">AI-world visual design handoff<a class="header-anchor" href="#ai-world-visual-design-handoff" aria-label="Link to this section">​</a></h1><p>Date: 2026-10-22. Method: built-in image generation (not CLI). Status: proposed visual concepts, not screenshots, production UI, Unity scenes, or import-ready 3D assets.</p><h2 id="ai-assistance-and-dispatch-island">AI assistance and dispatch island<a class="header-anchor" href="#ai-assistance-and-dispatch-island" aria-label="Link to this section">​</a></h2><p>Output: <code>docs/media/gdd/gameplay-first/ai-world.png</code> Dimensions: 1672 × 941 pixels, PNG, opaque. Caption: Lee&#39;s assistance center gives examples, new tests, and human approval separate physical stations on one compact island. Intended interaction: approach TRAIN to label fictional requests, TEST to inspect an unseen request and a model prediction, then APPROVE to authorize the small dispatch bot. Connect the route with ordinary movement and dialogue; retain visible landmarks. Save at station completion. Do not add these station locations as separate giant levels. Visual validation: isometric elevated environment, blue-haired/yellow-coated Explorer, white/cyan guide robot, smaller wheeled delivery bot, TRAIN/TEST/APPROVE labels all readable. The dispatch gate is closed until the learner approves the action. The training/test examples are visually separated. Caveats: foliage, water and stone detail are richer than a low-end production target. Simplify those surfaces and use measured device budgets, not the visual&#39;s apparent complexity. Bins must receive explicit text/symbol labels ROUTINE and REVIEW in production, not rely on red/green. This image does not establish runtime performance, exact collision geometry or asset licensing. The tree and some guide proportions differ from approved references; treat as a direction proposal. No final 3D source assets were generated. Proposed ownership: Luis for world assets; Miguel for station UI; Christian for interactions; Sherwin approves visual/gameplay direction.</p><h3 id="exact-generation-prompt">Exact generation prompt<a class="header-anchor" href="#exact-generation-prompt" aria-label="Link to this section">​</a></h3><pre><code class="language-text">Use case: stylized-concept
Asset type: landscape game environment concept for the Chainy educational game design document, 16:9 wide.
Primary request: An AI assistance and dispatch center on a small explorable island. Orthographic isometric camera elevated 40 degrees; the whole compact traversable stone platform and its connected stations are visible. Restrained, angular low-poly 3D style, faceted mossy limestone ruins, olive grass, sparse flowers, rich blue surrounding water, warm late afternoon light, long crisp shadows, controlled subtle cyan glow. A small blue-haired Explorer wearing a yellow coat and backpack stands at the teaching desk. Lee is a friendly white faceted robot with a black screen face and cyan eyes, next to the Explorer. Preserve a restrained adventurous material language, not a rounded plastic toy scene.
Scene: one compact island with three clearly readable stations connected by stone paths. The teaching desk holds a few large request cards and two bins. Farther along is a physically separate testing desk holding sealed new request cards. A small delivery bot waits beside a human-approval console before a closed dispatch gate. Background ruined dispatch tower suggests restoring a community service, not a threatening laboratory. Stone steps and paths show the playable route, uncluttered navigation, no isolated unreachable prop islands.
Text: Only three small station plaques with exact text &quot;TRAIN&quot;, &quot;TEST&quot;, &quot;APPROVE&quot;. No other text, floating HUD, statistics or logos.
Learning constraints: Teaching examples and new test examples are separate; a learner checks requests and approves the bot before dispatch. No blockchain cubes as AI model, no guarantee of fraud detection, no autonomous money transfer, no live chat service, no floating brain. Distinguish the guide robot and smaller delivery bot.
Composition: environment dominates, characters small and naturally within scene. Keep bottom corners free of busy props for later mobile controls. Concept art only, no phone frame, no watermark.
</code></pre><h2 id="teach-and-test-mobile-interface">Teach-and-test mobile interface<a class="header-anchor" href="#teach-and-test-mobile-interface" aria-label="Link to this section">​</a></h2><p>Output: <code>docs/media/gdd/gameplay-first/ai-training.png</code> Dimensions: 1672 × 941 pixels, PNG, opaque. Caption: Example labels teach the model; new requests test it. Amount alone does not decide whether a request needs review. Intended interaction: the left panel depicts assigned training labels. In the playable UI each card needs both choices before selection; the illustration&#39;s single per-card label is the selected-label state, not the entire interaction. Teach Bot updates a tiny actual local classifier or must be honestly labelled a scripted demonstration. The right panel shows a potentially mistaken prediction; the learner must open evidence and choose an answer. A final neutral approval/hold confirmation occurs after evidence review and before any fictional dispatch. Exact content: 80-coin legitimate community repair labelled ROUTINE, 2-coin unknown request asking for a secret phrase labelled REVIEW, unseen 60-coin school-supplies request with a provisional bot REVIEW prediction. Verification needs more than amount or familiarity alone; supporting evidence must explain purpose, recipient and requested permissions. Visual validation: TRAIN and NEW TEST distinct, Lee portraits named correctly, all requested text legible, neutral outlined choices, no made-up accuracy/confidence meter, footer explicitly reserves approval for a person. Caveats: the final revised illustration uses a neutral envelope/request icon; suspicious behavior is the secret-phrase request, not clothing or identity. The 60-coin card must not let the learner infer a final label from amount/known recipient alone: evidence detail must exist. Train labels are the selected-label state after the learner assigns labels, not an unselected quiz or the full interaction. A full design needs unselected, selected, wrong/review feedback, disabled, loading and completed states. Two panels side-by-side are a GDD comparison sheet, not a single mobile screen. Implement one landscape panel at a time with readable scaled text and large tested touch targets. Final independent assessment uses fresh examples, not repeatedly practiced test cards. Proposed ownership: Miguel creates native UI; Luis supplies clean card icons; Christian implements training/inference and evidence interactions; Sean documents teaching limits.</p><h3 id="exact-generation-prompt-1">Exact generation prompt<a class="header-anchor" href="#exact-generation-prompt-1" aria-label="Link to this section">​</a></h3><pre><code class="language-text">Use case: ui-mockup
Asset type: landscape mobile-game interface concept sheet for Chainy&#39;s game design document, widescreen 16:9, two equal landscape gameplay interface panels side by side on a quiet dark navy background. Not a real game screenshot.
Primary request: Show a teach-and-test interaction for a small fictional request-classification model, for students aged 12–17. Restrained dark-navy translucent panels with thin cyan edges, off-white bold readable typography, simple faceted illustrated request cards. A small friendly white faceted screen-face robot with cyan eyes named Lee appears as a portrait. Sparse mossy limestone island background behind each panel, fixed orthographic elevated isometric style. No phone bezels or decorative device frames. Large touch targets. Text must be sparse and render exactly.
Left panel header text: &quot;TRAIN&quot;
A short explanation: &quot;Label examples&quot;
Two large example cards.
Card 1 exact text: &quot;80 COINS&quot;, &quot;Community repair&quot;, &quot;Trusted request&quot; and a prominent neutral outlined button &quot;ROUTINE&quot;.
Card 2 exact text: &quot;2 COINS&quot;, &quot;Unknown sender&quot;, &quot;Asks for secret phrase&quot; and a prominent neutral outlined button &quot;REVIEW&quot;.
A bottom button &quot;TEACH BOT&quot;.
Under left panel, exact caption: &quot;Examples change the model.&quot;
Right panel header text: &quot;NEW TEST&quot;
Short explanation: &quot;Check an unseen request&quot;
One large test card exact text: &quot;60 COINS&quot;, &quot;School supplies&quot;, &quot;Known recipient&quot;.
A small bot speech panel text: &quot;Bot: REVIEW&quot;.
Below it, a simple evidence panel exact text: &quot;Verify the purpose and recipient.&quot;
Two large neutral outlined buttons: &quot;ROUTINE&quot; and &quot;REVIEW&quot;.
At bottom a button &quot;CHECK EVIDENCE&quot;.
Under right panel, exact caption: &quot;A prediction can be wrong.&quot;
Page footer exact text: &quot;Training and test cards are separate. A person approves any action.&quot;
Learning constraints: Intentionally show a large legitimate training request classified routine and a small suspicious secret-phrase request classified needs review, so size alone is not a verdict. The test bot prediction is explicitly only a prediction and not shown as correct before the learner checks. Never display percentages, confidence meters, guaranteed fraud detection, blockchain consensus, live LLM, actual learner data, real wallet balances, or a real seed phrase.
Composition: Two clear equal-width panels, strong hierarchy and ample padding; request cards and buttons large enough to read as a document illustration; use shapes and labels, not color alone. No extra text, no logos, no watermark.
</code></pre><h3 id="final-targeted-revision-prompt">Final targeted revision prompt<a class="header-anchor" href="#final-targeted-revision-prompt" aria-label="Link to this section">​</a></h3><p>The built-in image editor replaced only the hooded illustration with a neutral request icon. The final saved output was re-inspected: all wording, amounts, layout, other illustrations and footer remain visually intact.</p><pre><code class="language-text">Use case: precise-object-edit
Edit target: the supplied Chainy TRAIN / NEW TEST interface concept sheet.
Change only the illustration in the top portion of the &quot;2 COINS&quot; training example card: remove the hooded person entirely and replace it with a neutral faceted request-card/account icon (a plain envelope or document with a simple question-mark badge). The icon should communicate missing sender information, not imply danger based on appearance. Match the restrained low-poly illustration materials and lighting of the other cards.
Preserve everything else exactly: canvas size, two-panel layout, backgrounds, all letters and words, all amounts, buttons, robot portraits, cyan outlines, panel spacing, all other illustrations and the footer. In particular preserve &quot;Asks for secret phrase&quot;, &quot;REVIEW&quot;, and &quot;Bot: REVIEW&quot; without changing text. Do not add any new wording, captions, symbols outside the replaced illustration, decorative details, watermarks, or screen elements. Preserve opaque background.
</code></pre><h2 id="productionimport-notes">Production/import notes<a class="header-anchor" href="#productionimport-notes" aria-label="Link to this section">​</a></h2><ul><li>Keep these PNGs in the design-document reference folder, not automatically in runtime builds.</li><li>Rebuild interfaces with native Unity UI and editable text; do not ship a flat image as controls.</li><li>Maintain a fixed orthographic camera, simple faceted geometry, restrained cyan feedback and mossy stone/grass palette; exact angle should be validated in the real scene.</li><li>Native assets need editable sources, license/source records, collision/navigation setup and performance-tested import settings. No texture size, memory or frame-time budget is claimed here.</li><li>AI advice is not blockchain consensus. No live LLM, real account, student dataset, real crypto or seed phrase is present.</li><li>Synthetic examples demonstrate errors and human review, not reliable fraud detection or a guarantee of safe requests.</li></ul></div>`,1)])])}const m=t(s,[["render",i]]);export{h as __pageData,m as default};
